def _tokens(pointer):
    if not isinstance(pointer, str):
        raise KeyError(pointer)
    if pointer == '':
        return []
    if not pointer.startswith('/'):
        raise KeyError(pointer)
    return [t.replace('~1', '/').replace('~0', '~') for t in pointer[1:].split('/')]


def _index(token, length, allow_end=False):
    if not token or not all('0' <= c <= '9' for c in token):
        raise KeyError(token)
    i = int(token)
    limit = length if allow_end else length - 1
    if i > limit:
        raise KeyError(token)
    return i


def _step(node, token):
    if isinstance(node, dict):
        try:
            return node[token]
        except KeyError:
            raise KeyError(token)
    if isinstance(node, list):
        return node[_index(token, len(node))]
    raise KeyError(token)


def resolve(doc, pointer):
    node = doc
    for token in _tokens(pointer):
        node = _step(node, token)
    return node


def set_at(doc, pointer, value):
    tokens = _tokens(pointer)
    if not tokens:
        raise KeyError(pointer)
    node = doc
    for token in tokens[:-1]:
        node = _step(node, token)
    last = tokens[-1]
    if isinstance(node, dict):
        node[last] = value
    elif isinstance(node, list):
        if last == '-':
            node.append(value)
        else:
            node[_index(last, len(node))] = value
    else:
        raise KeyError(last)
    return None

